package com.nse.dashboard.agent;import com.nse.dashboard.model.ParticipantData;import org.springframework.stereotype.Component;import java.util.*;@Component public class SmartMoneyAgent { public String analyze(List<ParticipantData> data){ double fii=0,dii=0; for(ParticipantData d:data){ if(d.getCategory().contains("FII"))fii=d.getNetValue(); if(d.getCategory().contains("DII"))dii=d.getNetValue();} if(fii<0&&dii>0)return"Conflict"; if(fii>0&&dii>0)return"Strong Bullish"; if(fii<0&&dii<0)return"Bearish"; return"Neutral";}}